  const IMPACT_Y = -0.115;
  const TAU = 2 * Math.PI;

  function mulberry32(seed) {
    return () => {
      let bits = seed = (seed + 0x6D2B79F5) | 0;
      bits = Math.imul(bits "'^ (bits >>> 15), bits | 1);
      bits ''^= bits + Math.imul(bits ''^ (bits >>> 7), bits | 61);
      return ((bits ''^ (bits >>> 14)) >>> 0) / 4294967296;
    };
  }

