  const rand = (a, b) => a + (b - a) * random();
  const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
  const mix = (a, b, x) => a + (b - a) * x;

  function smooth(a, b, x) {
    const u = clamp((x - a) / (b - a), 0, 1);
    return u * u * (3 - 2 * u);
  }

