  renderer.outputEncoding = THREE.sRGBEncoding;
  renderer.setClearColor(0x000000, 0);

  const scene = new THREE.Scene();
  const camera = new THREE.OrthographicCamera(-6, 6, 3.4, -3.4, 0.1, 40);
  camera.position.set(0, 0, 14);
  const capture = new THREE.WebGLRenderTarget(1, 1, {
    minFilter: THREE.LinearFilter,
    magFilter: THREE.LinearFilter,
    generateMipmaps: false
  });
  const viewport = { value: new THREE.Vector2() };
  const pixelsPerUnit = { value: 1 };
  const opticalTime = { value: 0 };
  const fieldSeed = { value: rand(0.25, 2.75) };
  const linear = color => new THREE.Color(color).convertSRGBToLinear();

  function addLight(color, intensity, x, y, z) {
    const light = new THREE.DirectionalLight(color, intensity);
    light.position.set(x, y, z);
    scene.add(light);
  }

  addLight(0xffe6df, 2.0, -3, 4.5, 6);
  addLight(0xd3f4ff, 2.3, -4.5, 1, -2.4);
  addLight(0xffbdd9, 1.65, 5, 1.4, -2.8);

  // The same studio panels light the latex, metal, and liquid interfaces.
  const studio = §
    float panel(vec3 ray, vec3 dir, vec2 size, float feather) {
      dir = normalize(dir);
      vec3 across = normalize(vec3(dir.z, 0.0, -dir.x));
      vec3 up = cross(dir, across);
      float facing = dot(ray, dir);
      vec2 uv = abs(vec2(dot(ray, across), dot(ray, up))) / max(facing, 0.001);
      vec2 light = 1.0 - smoothstep(size * (1.0 - feather), size, uv);
      return step(0.0, facing) * light.x * light.y;
    }

    vec3 studioReflection(vec3 ray) {
      float key = panel(ray, vec3(-0.72, 0.76, 1.0), vec2(0.23, 0.54), 0.43);
      float keySeam = panel(ray, vec3(-1.03, 0.74, 1.0), vec2(0.034, 0.44), 0.39);
      float rim = panel(ray, vec3(-1.0, 0.08, -0.39), vec2(0.31, 0.88), 0.42);
      float strip = panel(ray, vec3(0.92, 0.21, 0.22), vec2(0.11, 0.77), 0.44);
      float kicker = panel(ray, vec3(1.0, 0.30, -0.69), vec2(0.32, 0.67), 0.52);
      float bounce = panel(ray, vec3(0.32, -0.83, 0.52), vec2(0.59, 0.12), 0.73);
      return key * vec3(1.29, 1.14, 1.07)
           + keySeam * vec3(0.31, 0.41, 0.48)
           + rim * vec3(0.70, 1.12, 1.44)
           + strip * vec3(0.92, 1.03, 1.22)
           + kicker * vec3(1.10, 0.48, 0.69)
           + bounce * vec3(0.09, 0.16, 0.25);
    }

    vec3 faceNormal(vec3 n) {
      return normalize(gl_FrontFacing ? n : -n);
    }
  §;

  const surfaceVertex = §
    attribute vec3 rest;
    attribute float lip;
    varying vec3 vNormal;
    varying vec3 vRest;
    varying vec3 vPlace;
    varying float vLip;

    void main() {
      vNormal = normalMatrix * normal;
      vRest = rest;
      vPlace = (modelMatrix * vec4(position, 1.0)).xyz;
      vLip = lip;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  §;

  const latexMaterial = new THREE.ShaderMaterial({
    vertexShader: surfaceVertex,
    uniforms: {
      time: opticalTime,
      seed: fieldSeed,
      pigment: { value: linear('#e61c24') },
      opacity: { value: 1 },
      puncture: { value: 1 },
      impact: { value: new THREE.Vector3() }
    },
    transparent: true,
    side: THREE.DoubleSide,
    fragmentShader: studio + §
      uniform float time;
      uniform float seed;
      uniform vec3 pigment;
      uniform float opacity;
      uniform float puncture;
      uniform vec3 impact;
      varying vec3 vNormal;
      varying vec3 vPlace;
      varying vec3 vRest;
      varying float vLip;

      void main() {
        vec3 p = vRest - impact;
        float fiber = sin(vRest.y * 108.0 + sin(vRest.z * 67.0 + seed));
        float hole = length(p * vec3(0.75, 0.99, 1.0)) + fiber * 0.008;
        float radius = smoothstep(1.065, 1.26, time) * 0.30;
        if (puncture > 0.5 && radius > 0.0 && hole < radius) discard;
        float edge = puncture * step(0.008, radius) * (1.0 - smoothstep(0.0, 0.027, hole - radius));
        vec3 n = faceNormal(vNormal);
        n = normalize(n + 0.006 * vec3(fiber, sin(vRest.x * 136.0 + seed), 0.0));
        vec3 view = vec3(0.0, 0.0, 1.0);
        float fresnel = pow(1.0 - max(dot(n, view), 0.0), 3.2);
        float key = max(dot(n, normalize(vec3(-0.44, 0.61, 0.78))), 0.0);
        float fill = max(dot(n, normalize(vec3(0.78, 0.06, 0.5))), 0.0);
        float rim = abs(n.x) * (0.50 + 0.50 * smoothstep(-1.4, 1.4, vPlace.y));
        vec3 soft = studioReflection(reflect(-view, n));
        vec3 color = pigment * (0.108 + key * 0.60 + fill * 0.21 + 0.015 * fiber);
        color += vec3(0.58, 0.022, 0.038) * (0.64 * fresnel * rim + 0.30 * vLip);
        color += soft * (0.29 + 0.72 * fresnel + 0.12 * vLip);
        color += vec3(0.38, 0.055, 0.043) * edge;
        gl_FragColor = vec4(color, opacity * (0.965 + 0.033 * fresnel));
        #include <encodings_fragment>
      }
    §
  });

  const liquidFragment = studio + §
    uniform sampler2D layer;
    uniform vec2 viewport;
    uniform float time;
    uniform float seed;
    uniform vec3 backdropCenter;
    uniform vec3 backdropEdge;
    uniform float thin;
    varying vec3 vNormal;
    varying vec3 vPlace;
    varying vec3 vRest;
    varying float vLip;

    void main() {
      float folds = sin(vRest.x * 13.0 + vRest.y * 7.0 + sin(vRest.z * 14.0 + seed))
                  * cos(vRest.z * 17.0 - vRest.y * 9.0 + seed);
      float cells = 0.54 * folds
                  + 0.31 * sin(vRest.y * 23.0 - vRest.x * 15.0 + sin(vRest.z * 10.0))
                  + 0.15 * cos(vRest.z * 32.0 + vRest.x * 18.0);
      float level = mix(-1.19, 1.14, smoothstep(4.93, 5.92, time));
      float gap = cells - level - 0.14 * vRest.y;
      if (thin < 0.5 && gap < 0.0) discard;
      if (thin > 0.5 && vLip < 0.44) discard;
      if (thin < 0.5 && vPlace.y < -2.80) discard;

      vec3 n = faceNormal(vNormal);
      float caustic = sin(vPlace.y * 29.0 - vPlace.x * 9.0 + 3.0 * folds + seed);
      float ripples = smoothstep(1.10, 1.60, time);
      n = normalize(n + vec3(0.018 * folds, 0.022 * caustic, 0.004 * folds) * ripples);
      vec3 view = vec3(0.0, 0.0, 1.0);
      float facing = max(0.0, dot(n, view));
      float fresnel = pow(1.0 - facing, 3.4);
      vec3 reflection = studioReflection(reflect(-view, n));
      float edge = pow(1.0 - facing, 5.0);
      float capillary = thin > 0.5 ? 1.0 - smoothstep(0.58, 0.74, vLip)
                                   : (1.0 - smoothstep(0.0, 0.18, gap)) * smoothstep(4.92, 5.21, time);

      vec2 uv = gl_FragCoord.xy / viewport;
      vec2 aspect = vec2(viewport.y / viewport.x, 1.0);
      vec2 refracted = uv + n.xy * aspect * (0.027 + 0.018 * fresnel);
      vec4 under = texture2D(layer, clamp(refracted, 0.0, 1.0));
      float falloff = length((refracted - 0.5) * vec2(viewport.x / viewport.y, 1.0))
                    / length(vec2(0.5 * viewport.x / viewport.y, 0.5));
      vec3 background = mix(backdropCenter, backdropEdge, clamp(falloff, 0.0, 1.0));
      vec3 transmitted = background * (1.0 - under.a) + under.rgb;
      float silver = pow(max(0.0, caustic), 10.0) * (0.30 + 0.70 * fresnel);
      float lightSide = 0.36 + 0.64 * smoothstep(-1.0, 0.35, -n.x + n.y * 0.40);
      vec3 color = transmitted * vec3(0.72, 0.89, 0.94) * (1.0 - 0.49 * fresnel);
      color += vec3(0.010, 0.020, 0.032) * (facing + 0.28 + folds * 0.24);
      color += reflection * (0.38 + 0.91 * fresnel + 0.22 * capillary);
      color += vec3(0.22, 0.43, 0.57) * (edge * lightSide * 0.86 + 0.30 * capillary + 0.22 * silver);
      color += vec3(0.23, 0.16, 0.21) * edge * smoothstep(0.1, 1.0, n.x) * 0.53;
      float alpha = thin > 0.5 ? clamp((0.47 + 0.38 * fresnel + 0.17 * capillary) * vLip, 0.0, 1.0) : 1.0;
      gl_FragColor = vec4(color, alpha);
      #include <encodings_fragment>
    }
  §;

  const liquidUniforms = {
    layer: { value: capture.texture },
    viewport,
    time: opticalTime,
    seed: fieldSeed,
    backdropCenter: { value: linear('#161922') },
    backdropEdge: { value: linear('#090a0f') }
  };

  const waterMaterial = new THREE.ShaderMaterial({
    vertexShader: surfaceVertex,
    fragmentShader: liquidFragment,
    uniforms: { ...liquidUniforms, thin: { value: 0 } }
  });

  const sheetMaterial = new THREE.ShaderMaterial({
    vertexShader: surfaceVertex,
    fragmentShader: liquidFragment,
    uniforms: { ...liquidUniforms, thin: { value: 1 } },
    side: THREE.DoubleSide,
    transparent: true,
    depthWrite: false
  });
